-- 20261102_language_canonical_fry.sql — NOT YET APPLIED (job #43, 2026-11-02). Needs Tom's go / Watson.
--
-- Western Frisian (fry_for_eng) had no database_code in tools/sync/reference/language_codes.csv,
-- so every Record Room take Auke uploaded for fry_for_eng on 2026-11-02 was stored in S3 but
-- refused filing: "cannot canonicalise language "fry"". The CSV now carries `fy → fry`, which
-- fixes the JavaScript canonicaliser; this adds the same two rows to the DB-side lookup that
-- canonical_language() reads (generated by tools/generate-language-canonical-sql.cjs, and spliced
-- into 20260806_clip_identity_canonical_functions.sql as that file's header says to).
--
-- Additive and idempotent: two INSERTs, no existing row touched.
-- Rollback: DELETE FROM language_canonical WHERE raw IN ('fry','fy') AND canonical = 'fry';

INSERT INTO language_canonical (raw, canonical) VALUES
  ('fry','fry'),
  ('fy','fry')
ON CONFLICT DO NOTHING;
